CREATE TABLE public.workforce_payroll_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),payroll_run_id uuid NOT NULL REFERENCES public.payroll_runs(id),employee_id uuid NOT NULL,basis text NOT NULL,rate numeric NOT NULL,hours jsonb NOT NULL,shift_ids uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workforce_payroll_snapshots TO authenticated; GRANT ALL ON public.workforce_payroll_snapshots TO service_role;
ALTER TABLE public.workforce_payroll_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_payroll_snapshot_read ON public.workforce_payroll_snapshots FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND public.has_workspace_access(auth.uid(),'payroll') AND public.is_admin_or_manager(auth.uid()));
CREATE OR REPLACE FUNCTION public.validate_workforce_pay(_employee uuid,_start date,_end date,_basic numeric,_ot numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.payroll_employee_directory; h jsonb; rate numeric; expected numeric; overtime numeric; BEGIN SELECT * INTO e FROM public.payroll_employee_directory WHERE user_id=_employee AND org_id=public.current_org_id(); IF e.user_id IS NULL THEN RAISE EXCEPTION 'Employee company required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() AND attendance_payroll) OR e.hr_details->>'pay_frequency' NOT IN ('Hourly','Daily') THEN RAISE EXCEPTION 'Attendance payroll is not configured'; END IF; PERFORM 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() FOR SHARE; PERFORM 1 FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=_employee AND shift_date BETWEEN _start AND _end FOR UPDATE; h:=public.workforce_pay_hours(_employee,_start,_end); IF (h->>'pending')::integer>0 OR (h->>'shifts')::integer=0 THEN RAISE EXCEPTION 'Attendance review required before payroll'; END IF; rate:=coalesce(nullif(e.hr_details->>'pay_rate',''),'0')::numeric; IF e.hr_details->>'pay_frequency'='Daily' THEN IF coalesce(e.std_hours_per_day,0)<=0 THEN RAISE EXCEPTION 'Daily hours required'; END IF; rate:=rate/e.std_hours_per_day; END IF; expected:=round(rate*(h->>'regular')::numeric,2); overtime:=round(rate*(h->>'overtime')::numeric*(h->>'multiplier')::numeric,2); IF _basic IS NULL OR _ot IS NULL OR rate<=0 OR abs(_basic-expected)>0.01 OR abs(_ot-overtime)>0.01 THEN RAISE EXCEPTION 'Attendance or pay rate changed; refresh payroll'; END IF; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='record_workforce_punch'; d:=replace(d,'IF _direction=''clock_in'' AND sh.id IS NOT NULL THEN','IF sh.id IS NOT NULL AND EXISTS(SELECT 1 FROM public.workforce_payroll_snapshots WHERE org_id=_org AND employee_id=_employee AND sh.id=ANY(shift_ids)) THEN RAISE EXCEPTION ''This shift has already been paid; ask your manager''; END IF; IF _direction=''clock_in'' AND sh.id IS NOT NULL THEN'); EXECUTE d; SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='approve_payroll_run'; d:=replace(d,'PERFORM public.apply_payroll_loans(run,p.user_id,f,coalesce((row->>''loan_deductions'')::numeric,0));', 'IF EXISTS(SELECT 1 FROM public.workforce_clock_settings WHERE org_id=public.current_org_id() AND attendance_payroll) AND p.hr_details->>''pay_frequency'' IN (''Hourly'',''Daily'') THEN INSERT INTO public.workforce_payroll_snapshots(org_id,payroll_run_id,employee_id,basis,rate,hours,shift_ids) VALUES(public.current_org_id(),run,p.user_id,p.hr_details->>''pay_frequency'',(p.hr_details->>''pay_rate'')::numeric,public.workforce_pay_hours(p.user_id,_start,_end),ARRAY(SELECT id FROM public.workforce_shifts WHERE org_id=public.current_org_id() AND employee_id=p.user_id AND shift_date BETWEEN _start AND _end)); END IF; PERFORM public.apply_payroll_loans(run,p.user_id,f,coalesce((row->>''loan_deductions'')::numeric,0));'); EXECUTE d; END $$;